    updated_by integer,
    updated_at timestamp without time zone DEFAULT now() NOT NULL,
    is_emergency_override boolean DEFAULT false NOT NULL,
    emergency_contact_email character varying(255),
    CONSTRAINT valid_effective_range CHECK (((effective_until IS NULL) OR (effective_until >= effective_from))),
    CONSTRAINT valid_fall_end_day CHECK (((fall_end_day >= 1) AND (fall_end_day <= 31))),
    CONSTRAINT valid_fall_end_month CHECK (((fall_end_month >= 1) AND (fall_end_month <= 12))),
    CONSTRAINT valid_fall_start_day CHECK (((fall_start_day >= 1) AND (fall_start_day <= 31))),
    CONSTRAINT valid_fall_start_month CHECK (((fall_start_month >= 1) AND (fall_start_month <= 12))),
    CONSTRAINT valid_spring_end_day CHECK (((spring_end_day >= 1) AND (spring_end_day <= 31))),
    CONSTRAINT valid_spring_end_month CHECK (((spring_end_month >= 1) AND (spring_end_month <= 12))),
    CONSTRAINT valid_spring_start_day CHECK (((spring_start_day >= 1) AND (spring_start_day <= 31))),
    CONSTRAINT valid_spring_start_month CHECK (((spring_start_month >= 1) AND (spring_start_month <= 12)))
);


