--
-- Name: student_attendance_summary; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.student_attendance_summary AS
 SELECT s.id AS student_id,
    s.student_id AS student_number,
    u.full_name,
    s.faculty AS class_name,
    s.year,
    count(ar.id) AS total_records,
    count(
        CASE
            WHEN (ar.status = 'present'::public.attendance_status) THEN 1
            ELSE NULL::integer
        END) AS present_count,
    count(
        CASE
            WHEN (ar.status = 'absent'::public.attendance_status) THEN 1
            ELSE NULL::integer
        END) AS absent_count,
    count(
        CASE
            WHEN (ar.status = 'late'::public.attendance_status) THEN 1
            ELSE NULL::integer
        END) AS late_count,
    round((((count(
        CASE
            WHEN (ar.status = 'present'::public.attendance_status) THEN 1
            ELSE NULL::integer
        END))::numeric * 100.0) / (NULLIF(count(ar.id), 0))::numeric), 2) AS attendance_percentage,
    max(ar.date) AS last_attendance_date
   FROM ((public.students s
     JOIN public.users u ON ((s.user_id = u.id)))
     LEFT JOIN public.attendance_records ar ON ((s.id = ar.student_id)))
  GROUP BY s.id, s.student_id, u.full_name, s.faculty, s.year;


